(()=>{document.querySelectorAll('.journey-picker').forEach(picker=>{const preview=picker.querySelector('.journey-preview p');picker.querySelectorAll('.journey-choice').forEach(a=>{const show=()=>{preview.textContent=a.dataset.description;};a.addEventListener('pointerenter',show);a.addEventListener('focus',show);});if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){picker.classList.add('arrived');observer.disconnect();}},{threshold:.15});observer.observe(picker);}});})();
(()=>{const reduced=matchMedia('(prefers-reduced-motion: reduce)');const veil=document.createElement('div');veil.className='section-gateway'+(document.querySelector('.journey-hvacr')?' blue':'');veil.setAttribute('aria-hidden','true');const label=document.createElement('span');veil.append(label);document.body.append(veil);document.querySelectorAll('.journey-choice').forEach(a=>a.addEventListener('click',e=>{if(reduced.matches||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey||e.button!==0)return;const target=document.getElementById(a.hash.slice(1));if(!target)return;e.preventDefault();label.textContent=a.querySelector('strong').textContent;veil.style.setProperty('--entry-x',(e.clientX||innerWidth/2)+'px');veil.style.setProperty('--entry-y',(e.clientY||innerHeight/2)+'px');veil.classList.add('active');setTimeout(()=>{location.hash=a.hash;target.scrollIntoView({behavior:'instant',block:'start'});target.setAttribute('tabindex','-1');target.focus({preventScroll:true});setTimeout(()=>veil.classList.remove('active'),220);},350);}));addEventListener('pageshow',()=>veil.classList.remove('active'));})();
